class Solution {
  public int primeSubarray(int[] nums, int k) {
    int n = nums.length, MAXV = 50_000;
    boolean[] composite = new boolean[MAXV + 1];
    composite[0] = composite[1] = true;
    for (int i = 2; i * i <= MAXV; i++)
      if (!composite[i]) for (int j = i * i; j <= MAXV; j += i) composite[j] = true;
    int[] maxDq = new int[n], minDq = new int[n];
    int mh = 0, mt = 0, nh = 0, nt = 0;
    int left = 0, last1 = -1, last2 = -1;
    long ans = 0;
    for (int r = 0; r < n; r++) {
      if (!composite[nums[r]]) {
        while (mt > mh && nums[maxDq[mt - 1]] <= nums[r]) mt--;
        maxDq[mt++] = r;
        while (nt > nh && nums[minDq[nt - 1]] >= nums[r]) nt--;
        minDq[nt++] = r;
        last2 = last1;
        last1 = r;
      }
      while (mt > mh && nums[maxDq[mh]] - nums[minDq[nh]] > k) {
        left++;
        while (mt > mh && maxDq[mh] < left) mh++;
        while (nt > nh && minDq[nh] < left) nh++;
      }
      if (last2 >= left) ans += last2 - left + 1;
    }
    return (int) ans;
  }
}
